mapper.insert:
INSERT INTO notification_send_history (
    request_id, source_type, plugin_id, instance_id, job_id, execution_id, channel_id, channel_type,
    title, severity, content_preview, content_payload, payload_bytes, labels_json, status, max_attempts
) VALUES (
    #{requestId}, #{sourceType}, #{pluginId}, #{instanceId}, #{jobId}, #{executionId}, #{channelId}, #{channelType},
    #{title}, #{severity}, #{contentPreview}, #{contentPayload}, #{payloadBytes}, CAST(#{labelsJson} AS JSON), #{status}, #{maxAttempts}
)

mapper.update:
UPDATE notification_send_history
SET status = #{retryWaitingStatus}, next_retry_at = #{now}, locked_at = NULL, locked_by = NULL, error_type = #{errorType}, error_message = #{errorMessage}, updated_at = CURRENT_TIMESTAMP(3)
WHERE status = #{sendingStatus} AND locked_at < #{staleBefore}

UPDATE notification_send_history
SET status = #{skippedStatus}, error_type = 'SKIPPED', error_message = #{message}, sent_at = CURRENT_TIMESTAMP(3), updated_at = CURRENT_TIMESTAMP(3)
WHERE id = #{id}

mapper.select:
SELECT *
FROM notification_send_history
WHERE status = #{failedStatus}
ORDER BY created_at DESC, id DESC
LIMIT #{limit}

mapper.delete:
DELETE FROM notification_send_history
WHERE created_at < #{cutoff}
ORDER BY id
LIMIT #{limit}
